func (s *Server) meta(r *http.Request) crm.RequestMeta {
	return crm.RequestMeta{Channel: func() string {
		p := auth.FromContext(r.Context())
		if p != nil && (p.AuthMethod == "PERSONAL_KEY" || p.AuthMethod == "OIDC_ACCESS_TOKEN") {
			return "API"
		}
		return "WEB"
	}(), IP: httpx.ClientIP(r), RequestID: httpx.RequestID(r.Context()), UserAgent: r.UserAgent()}
}
func principal(r *http.Request) *auth.Principal { return auth.FromContext(r.Context()) }
func (s *Server) serviceError(w http.ResponseWriter, r *http.Request, err error) {
	if err == nil {
		return
	}
	msg := err.Error()
	status := http.StatusBadRequest
	code := "invalid_request"
	sqlstate := ""
	var pgErr *pgconn.PgError
	isPg := errors.As(err, &pgErr) || strings.Contains(msg, "SQLSTATE")
	switch {
	case errors.Is(err, pgx.ErrNoRows) || msg == "no rows in result set":
		status = 404
		code = "not_found"
		// The driver's phrasing reached API and MCP clients verbatim.
		msg = "요청한 데이터를 찾을 수 없거나 접근 권한이 없습니다."
	case isPg:
		// A PostgreSQL error before the English substrings below, because they
		// read the driver's own sentence: "permission denied for table contacts"
		// left as a 403 carrying the table name, and "relation ... does not
		// exist" left as a 400 for what is a server defect. The same table is
		// in internal/mcp/results.go sanitizeToolError, which is how the MCP
		// path reads the same error; keep the two in step.
		if pgErr != nil {
			sqlstate = pgErr.Code
		}
		status, code, msg = pgErrorVerdict(sqlstate)
	case database.Unreachable(err):
		// PostgreSQL was never reached, so there is no SQLSTATE for the table
		// above to read and the default 400 used to hand the client the driver's
		// own sentence — which carries the database role, the database name and
		// the internal host:port. A database that went away is a server fault,
		// and the 5xx also keeps the idempotency cache from storing the answer.
		// This sits after isPg on purpose: a refused authentication wraps a
		// PgError (28P01) in a ConnectError, and that one should still log its
		// sqlstate. Both end as a 500. msg is left alone — the status >= 500
		// block below logs the original and replaces the sentence.
		status = http.StatusInternalServerError
		code = "internal_error"
	case database.Interrupted(err):
		// The query was cut short instead of answered — today almost always a
		// caller that went away, which makes net/http cancel r.Context(). There
		// is no SQLSTATE and no ConnectError, so this fell through to the default
		// 400 and told the client, the logs and the metrics that the input was
		// wrong while handing back the driver's "context canceled". This sits
		// after database.Unreachable on purpose: a dial that timed out wraps
		// context.DeadlineExceeded inside a *pgconn.ConnectError, and that one
		// must keep the verdict above so its sqlstate still reaches the log.
		// msg is left alone — the status >= 500 block below replaces it.
		status = http.StatusInternalServerError
		code = "internal_error"
	case strings.Contains(msg, "not found"):
		status = 404
		code = "not_found"
	case strings.Contains(msg, "permission") || strings.Contains(msg, "access denied") || strings.Contains(msg, "designated approver"):
		status = 403
		code = "forbidden"
	case strings.Contains(msg, "another user") || strings.Contains(msg, "already") || strings.Contains(msg, "pending"):
		status = 409
		code = "conflict"
	}
	if status >= 500 {
		s.Log.Error("service error", "error", err, "sqlstate", sqlstate, "requestId", httpx.RequestID(r.Context()))
		msg = "서버 오류가 발생했습니다."
	}
	httpx.ErrorJSON(w, r, status, code, msg, nil)
}

// pgErrorVerdict maps a SQLSTATE to the status, code and sentence a REST client
// receives. The sentences are the ones internal/mcp/results.go sanitizeToolError
// gives an MCP client for the same code, so one database error does not become
// two different answers depending on which door the caller came through. The
// two functions stay separate on purpose: MCP returns a string, REST returns a
// verdict, and internal/server already imports internal/mcp. An unrecognised
// code — including a missing one — is a server defect, not the caller's fault;
package mcp

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"strings"

	"github.com/hkjang/relio/internal/platform/database"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
)

// structuredObject shapes a tool's return value for structuredContent, which
// the specification defines as a JSON object. Twenty-four list tools returned a
// bare array there, and every client built on the official SDK validates the
// field: the call failed with "expected record" before the model saw a byte.
// A list becomes {items, count}, matching the paged tools, and a nil list
// becomes an empty one rather than null.
func structuredObject(v any) (map[string]any, []byte, error) {
	raw, err := json.Marshal(v)
	if err != nil {
		return nil, nil, fmt.Errorf("도구 결과를 JSON으로 만들 수 없습니다: %w", err)
	}
	trimmed := bytes.TrimSpace(raw)
	switch {
	case len(trimmed) == 0 || bytes.Equal(trimmed, []byte("null")):
		// A nil slice from an empty query. Nothing returns a nil single record
		// without an error, so an empty list is the honest reading.
		return map[string]any{"items": []any{}, "count": 0}, []byte("[]"), nil
	case trimmed[0] == '{':
		out := map[string]any{}
		if err := json.Unmarshal(trimmed, &out); err != nil {
			return nil, nil, err
		}
		return out, raw, nil
	case trimmed[0] == '[':
		items := []any{}
		if err := json.Unmarshal(trimmed, &items); err != nil {
			return nil, nil, err
		}
		return map[string]any{"items": items, "count": len(items)}, raw, nil
	default:
		var value any
		if err := json.Unmarshal(trimmed, &value); err != nil {
			return nil, nil, err
		}
		return map[string]any{"value": value}, raw, nil
	}
}

// sanitizeToolError turns an error into a sentence that is safe and useful to
// show a model. Database errors used to reach the client verbatim — "ERROR:
// invalid input syntax for type uuid (SQLSTATE 22P02)" — which exposes schema
// detail and gives the model nothing it can act on. The original is logged
// with the request id so an operator can still find it.
//
// The same SQLSTATE table is in internal/server/server.go pgErrorVerdict, which
// is how the REST path reads the same error. The sentences below are shared
// with it word for word; change one and change the other. The two stay separate
// because the return contracts differ — a string here, status+code+message
// there — and internal/server imports this package, not the other way round.
// internal/server/sqlstate_parity_test.go compares the two tables and fails
// when they drift.
func sanitizeToolError(err error, requestID string) string {
	message := err.Error()
	var arg *argumentError
	if errors.As(err, &arg) {
		return arg.message
	}
	if errors.Is(err, pgx.ErrNoRows) || message == "no rows in result set" || strings.HasSuffix(message, " not found") {
		return "요청한 데이터를 찾을 수 없거나 접근 권한이 없습니다."
	}
	var pgErr *pgconn.PgError
	// database.Unreachable and database.Interrupted are the two failures that
	// carry no SQLSTATE: the driver never reached PostgreSQL, or the query was
	// cut short by a cancelled or expired context. Without them this fell through
	// to the last line and handed the model the driver's own sentence — fragments
	// of the DSN in the first case, "context canceled" in the second. code stays
	// empty either way, so the switch below passes it through to the generic
	// sentence, which is what the REST door answers with for the same error.
	if errors.As(err, &pgErr) || strings.Contains(message, "SQLSTATE") || database.Unreachable(err) || database.Interrupted(err) {
		code := ""
		if pgErr != nil {
			code = pgErr.Code
		}
		slog.Warn("mcp tool database error", "error", message, "sqlstate", code, "requestId", requestID)
		switch code {
		case "22P02":
			return "입력 값의 형식이 올바르지 않습니다. ID는 목록·검색 도구가 돌려준 UUID를 그대로 사용하세요."
		case "22007", "22008":
			return "날짜 형식이 올바르지 않습니다. YYYY-MM-DD 형식을 사용하세요."
		case "22003":
			return "숫자가 허용 범위를 벗어났습니다."
		case "23505":
			return "같은 값이 이미 등록되어 있습니다. 기존 데이터를 조회해 수정하세요."
		case "23503":
			return "연결 대상이 없거나 다른 데이터가 참조하고 있어 처리할 수 없습니다."
		case "23502", "23514":
			return "필수 값이 비었거나 허용되지 않는 값입니다."
		case "40001", "40P01":
			return "동시에 처리된 다른 요청과 충돌했습니다. 잠시 후 다시 시도하세요."
		}
		return "데이터 처리 중 오류가 발생했습니다. 요청 ID: " + requestID
	}
	return message
}
#!/usr/bin/env bash
set -euo pipefail

if [ "$#" -ne 2 ]; then echo "usage: $0 <old-image> <new-image>" >&2; exit 2; fi
relio_old_image="$1"
relio_new_image="$2"
relio_upgrade_suffix="${GITHUB_RUN_ID:-local}-$$"
relio_upgrade_network="relio-upgrade-$relio_upgrade_suffix"
relio_upgrade_postgres="relio-upgrade-postgres-$relio_upgrade_suffix"
relio_upgrade_old="relio-upgrade-old-$relio_upgrade_suffix"
relio_upgrade_new="relio-upgrade-new-$relio_upgrade_suffix"
relio_upgrade_volume="relio-upgrade-data-$relio_upgrade_suffix"
relio_upgrade_state="$(mktemp /tmp/relio-upgrade-state.XXXXXX)"
relio_upgrade_workspace="$(pwd)"
# The old image ignores this variable; the new one must adopt it without
# invalidating the credentials the old image already encrypted.
relio_upgrade_encryption_key="72656c696f2d757067726164652d746573742d656e6372797074696f6e2d6b6579"

relio_expected_new_schema="$(find migrations -maxdepth 1 -type f -name '*.sql' -printf '%f\n' | sort | tail -n 1)"
if [ -z "$relio_expected_new_schema" ]; then echo "no migration found" >&2; exit 2; fi

cleanup() {
  docker rm -f "$relio_upgrade_old" "$relio_upgrade_new" "$relio_upgrade_postgres" >/dev/null 2>&1 || true
  docker network rm "$relio_upgrade_network" >/dev/null 2>&1 || true
  docker volume rm "$relio_upgrade_volume" >/dev/null 2>&1 || true
  rm -f "$relio_upgrade_state"
}
trap cleanup EXIT

wait_for_app() {
  local container="$1"
  for attempt in $(seq 1 60); do
    if docker exec "$container" /usr/local/bin/relio healthcheck >/dev/null 2>&1; then return; fi
    if [ "$attempt" -eq 60 ]; then docker logs "$container"; exit 1; fi
    sleep 1
  done
}

docker pull postgres:17-bookworm >/dev/null
docker pull python:3.13-slim >/dev/null
docker network create --internal "$relio_upgrade_network" >/dev/null
docker volume create "$relio_upgrade_volume" >/dev/null
docker run -d --name "$relio_upgrade_postgres" --network "$relio_upgrade_network" \
  -e POSTGRES_DB=relio -e POSTGRES_USER=relio -e POSTGRES_PASSWORD=upgrade-test-password \
  postgres:17-bookworm >/dev/null

for attempt in $(seq 1 60); do
  if docker exec "$relio_upgrade_postgres" pg_isready -U relio -d relio >/dev/null 2>&1; then break; fi
  if [ "$attempt" -eq 60 ]; then docker logs "$relio_upgrade_postgres"; exit 1; fi
  sleep 1
done

common_args=(
  --network "$relio_upgrade_network"
  -e "POSTGRES_DSN=postgres://relio:upgrade-test-password@$relio_upgrade_postgres:5432/relio?sslmode=disable"
  -e "BOOTSTRAP_ADMIN=admin"
  -e "BOOTSTRAP_ADMIN_PASSWORD=ChangeMe-Relio-Upgrade-2026"
  -v "$relio_upgrade_volume:/var/lib/relio"
)

docker run -d --name "$relio_upgrade_old" "${common_args[@]}" "$relio_old_image" >/dev/null
wait_for_app "$relio_upgrade_old"
docker run --rm --network "$relio_upgrade_network" \
  --mount "type=bind,src=$relio_upgrade_workspace/scripts/restart-persistence.py,dst=/restart-persistence.py,readonly" \
  --mount "type=bind,src=$relio_upgrade_state,dst=/restart-state.json" \
  python:3.13-slim python /restart-persistence.py setup "http://$relio_upgrade_old:8080" admin ChangeMe-Relio-Upgrade-2026 /restart-state.json Relio-Upgrade-Persistence-2026
relio_old_schema="$(docker exec "$relio_upgrade_postgres" psql -U relio -d relio -Atc "SELECT max(version) FROM schema_migrations")"
test -n "$relio_old_schema"
test "$(docker exec "$relio_upgrade_postgres" psql -U relio -d relio -Atc "SELECT count(*) FROM users WHERE is_bootstrap=true")" = "1"
docker rm -f "$relio_upgrade_old" >/dev/null

docker run -d --name "$relio_upgrade_new" "${common_args[@]}" \
  -e ENCRYPTION_KEY="$relio_upgrade_encryption_key" "$relio_new_image" >/dev/null
wait_for_app "$relio_upgrade_new"
docker run --rm --network "$relio_upgrade_network" \
  --mount "type=bind,src=$relio_upgrade_workspace/scripts/restart-persistence.py,dst=/restart-persistence.py,readonly" \
  --mount "type=bind,src=$relio_upgrade_state,dst=/restart-state.json,readonly" \
  python:3.13-slim python /restart-persistence.py verify "http://$relio_upgrade_new:8080" admin Relio-Upgrade-Persistence-2026 /restart-state.json portable
relio_new_schema="$(docker exec "$relio_upgrade_postgres" psql -U relio -d relio -Atc "SELECT max(version) FROM schema_migrations")"
test "$relio_new_schema" = "$relio_expected_new_schema"
test "$(docker exec "$relio_upgrade_postgres" psql -U relio -d relio -Atc "SELECT count(*) FROM users WHERE is_bootstrap=true")" = "1"
test "$(docker exec "$relio_upgrade_postgres" psql -U relio -d relio -Atc "SELECT count(*) FROM deal_health_rules WHERE active=true")" -ge 9
test "$(docker exec "$relio_upgrade_postgres" psql -U relio -d relio -Atc "SELECT count(*) FROM information_schema.columns WHERE table_name='contacts' AND column_name='relationship_role'")" = "1"

if [ "$relio_expected_new_schema" = "003_relationship_intelligence.sql" ]; then
  test "$(docker exec "$relio_upgrade_postgres" psql -U relio -d relio -Atc "SELECT count(*) FROM information_schema.tables WHERE table_schema='public' AND table_name IN ('contact_relationships','account_plans','opportunity_members')")" = "3"
  test "$(docker exec "$relio_upgrade_postgres" psql -U relio -d relio -Atc "SELECT count(*) FROM system_settings WHERE namespace='relationship_intelligence'")" = "3"
fi

test "$(docker exec "$relio_upgrade_postgres" psql -U relio -d relio -Atc "SELECT count(*) FROM instance_key_registry")" = "1"
test "$(docker exec "$relio_upgrade_postgres" psql -U relio -d relio -Atc "SELECT count(*) FROM information_schema.columns WHERE table_name='oidc_providers' AND column_name='version'")" = "1"

# The upgrade must wrap the pre-existing data key with ENCRYPTION_KEY instead of
# minting a new one, so credentials created by the old image keep working.
test "$(docker exec "$relio_upgrade_postgres" psql -U relio -d relio -Atc "SELECT wrap_origin FROM instance_data_key")" = "ENCRYPTION_KEY"
test "$(docker exec "$relio_upgrade_postgres" psql -U relio -d relio -Atc "SELECT count(*) FROM roles WHERE is_default")" = "1"

# Dropping the newly adopted key must fail closed rather than re-key the instance.
docker rm -f "$relio_upgrade_new" >/dev/null
docker run -d --name "$relio_upgrade_new" "${common_args[@]}" "$relio_new_image" >/dev/null
for attempt in $(seq 1 20); do
  relio_upgrade_state_status="$(docker inspect "$relio_upgrade_new" --format '{{.State.Status}}')"
  if [ "$relio_upgrade_state_status" = "exited" ] || [ "$relio_upgrade_state_status" = "dead" ]; then break; fi
  if [ "$attempt" -eq 20 ]; then echo "Relio started without the ENCRYPTION_KEY that wraps its data key" >&2; docker logs "$relio_upgrade_new"; exit 1; fi
  sleep 1
done
docker logs "$relio_upgrade_new" 2>&1 | grep -q "wrapped by ENCRYPTION_KEY"

echo "Relio upgrade test passed: $relio_old_schema -> $relio_new_schema"
