func (s *Server) customFields(w http.ResponseWriter, r *http.Request) {
	bundle, err := s.configurationBundle(r.Context(), p)
	if err != nil {
		s.serviceError(w, r, err)
		return
	}
	s.Audit.Record(r.Context(), audit.Event{ActorID: p.UserID, ActorName: p.Username, Channel: "ADMIN", Action: "CONFIGURATION_BUNDLE_EXPORT", Resource: "configuration", After: map[string]any{"format": bundle.Format, "sourceVersion": bundle.SourceVersion, "containsSecrets": false}, IP: httpx.ClientIP(r), RequestID: httpx.RequestID(r.Context()), UserAgent: r.UserAgent()})
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.Header().Set("Content-Disposition", `attachment; filename="relio-config-`+time.Now().UTC().Format("20060102T150405Z")+`.json"`)
	w.WriteHeader(http.StatusOK)
	_ = json.NewEncoder(w).Encode(bundle)
}

func (s *Server) previewConfiguration(w http.ResponseWriter, r *http.Request) {
	p := principal(r)
	if err := requireAdmin(p, false); err != nil {
		s.serviceError(w, r, err)
		return
	}
	var bundle configurationBundle
	if !httpx.DecodeJSON(w, r, &bundle) {
		return
		MinAgeDays:      httpx.IntQuery(r, "minAgeDays", 0, 0, 3650),
		Limit:           httpx.IntQuery(r, "limit", 200, 1, 200),
	})
	if err != nil {
		s.serviceError(w, r, err)
		return
	}
	s.Audit.Record(r.Context(), audit.Event{ActorID: p.UserID, ActorName: p.Username, Channel: "WEB",
		Action: "VOICE_EXPORT", Resource: "customer_voice",
		After: map[string]any{"rows": count, "filters": r.URL.RawQuery},
		IP:    httpx.ClientIP(r), RequestID: httpx.RequestID(r.Context()), UserAgent: r.UserAgent()})
	w.Header().Set("Content-Type", "text/csv; charset=utf-8")
	w.Header().Set("Content-Disposition", `attachment; filename="relio-voices-`+s.Clock.DateStamp(r.Context())+`.csv"`)
	w.WriteHeader(http.StatusOK)
	// Excel needs the BOM to read UTF-8 Korean correctly.
	_, _ = w.Write([]byte("\xef\xbb\xbf"))
	_, _ = w.Write([]byte(body))
}

func nullableID(v string) any {
	if strings.TrimSpace(v) == "" {
		return nil
	}
	return strings.TrimSpace(v)
}
